function wait(video,type,signal){return new Promise((resolve,reject)=>{const clear=()=>{clearTimeout(timer);video.removeEventListener(type,ok);video.removeEventListener('error',bad);signal?.removeEventListener('abort',abort)},ok=()=>{clear();resolve()},bad=()=>{clear();reject(Error('视频无法解码'))},abort=()=>{clear();reject(Error('分析已停止'))};const timer=setTimeout(()=>{clear();reject(Error('连续画面采样超时，请保持页面前台'))},15000);video.addEventListener(type,ok,{once:true});video.addEventListener('error',bad,{once:true});signal?.addEventListener('abort',abort,{once:true});if(signal?.aborted)abort()})}
export function intervalTimes(shot,duration){if(!Number.isFinite(duration)||duration<=0||!Number.isFinite(shot.start)||!Number.isFinite(shot.end)||shot.start<0||shot.end<=shot.start||shot.end>duration)throw Error('镜头范围无效');const start=Math.max(0,shot.start-.2),end=Math.min(duration-.001,shot.end+.2);return Array.from({length:12},(_,i)=>Number((start+(end-start)*(i+.5)/12).toFixed(4)))}
export async function captureInterval(url,shot,duration,signal,onProgress=()=>{}){const v=document.createElement('video');v.muted=true;v.playsInline=true;v.preload='auto';try{const ready=wait(v,'loadeddata',signal);v.src=url;v.load();await ready;const c=document.createElement('canvas'),scale=Math.min(480/v.videoWidth,480/v.videoHeight,1);c.width=Math.max(1,Math.round(v.videoWidth*scale));c.height=Math.max(1,Math.round(v.videoHeight*scale));const ctx=c.getContext('2d');const frames=[];for(const time of intervalTimes(shot,duration)){if(signal.aborted)throw Error('分析已停止');if(Math.abs(v.currentTime-time)>.0001){const seek=wait(v,'seeked',signal);v.currentTime=time;await seek}ctx.drawImage(v,0,0,c.width,c.height);frames.push({time,image:c.toDataURL('image/jpeg',.7)});onProgress(frames.length)}return frames}finally{v.pause();v.removeAttribute('src');v.load()}}
export function renderEffectResult(parent,result,index){const card=document.createElement('article');card.className='effect-analysis-card';const add=(tag,text,where=card)=>{const e=document.createElement(tag);e.textContent=text;where.append(e);return e};add('h4',`镜头 ${index+1} · ${result.shot.start.toFixed(2)}–${result.shot.end.toFixed(2)} 秒`);add('p','画面观察：'+result.observation);for(const effect of result.effects){const section=document.createElement('section');card.append(section);add('h4',effect.name+' · 模型自述把握：'+({medium:'中',low:'低',unknown:'不确定'}[effect.confidence]||'不确定'),section);add('p','采样证据：'+effect.evidenceTimes.map(t=>t.toFixed(2)+'s').join(' / ')+'；'+effect.reason,section);add('p','替代解释：'+effect.alternatives,section);const list=add('ol','',section);effect.steps.forEach(step=>add('li',step,list));add('p','试做参数（不是原参数）：'+effect.trialParameters,section);add('p','核对方法：'+effect.verify,section)}add('p','无法确定：'+result.unknowns);add('small',result.method+' · '+result.model);parent.append(card)}
